import React from "react";

function CustomerBlock({ index, block, customers, storages, categories, updateBlock, removeBlock }) {
  const updateProduct = (pi, field, value) => {
    const products = block.products.map((p, i) =>
      i === pi ? { ...p, [field]: value } : p
    );
    updateBlock({ ...block, products });
  };

  const addProduct = () => {
    updateBlock({ ...block, products: [...block.products, { name: "", weight: "", storageId: "" }] });
  };

  const removeProduct = (pi) => {
    const products = block.products.filter((_, i) => i !== pi);
    updateBlock({ ...block, products });
  };

  return (
    <div className="customer-block">
      <select
        value={block.customerId}
        onChange={(e) => updateBlock({ ...block, customerId: e.target.value })}
      >
        <option value="">Select Customer</option>
        {customers.map(c => (
          <option key={c.id} value={c.id}>{c.name}</option>
        ))}
      </select>

      {block.products.map((p, i) => (
        <div key={i} className="product-row">
          <select value={p.name} onChange={e => updateProduct(i, "name", e.target.value)}>
            <option value="">Select Category</option>
            {categories.map(cat => (
              <option key={cat.id} value={cat.name}>{cat.name}</option>
            ))}
          </select>
          <input
            type="text"
            value={p.weight}
            onChange={e => updateProduct(i, "weight", e.target.value)}
            placeholder="Weight"
          />
          <select value={p.storageId} onChange={e => updateProduct(i, "storageId", e.target.value)}>
            <option value="">Select Storage</option>
            {storages.map(s => (
              <option key={s.id} value={s.id}>{s.name}</option>
            ))}
          </select>
          <button onClick={() => removeProduct(i)}>x</button>
        </div>
      ))}

      <button onClick={addProduct}>+ Add Product</button>
      <button onClick={removeBlock}>Remove Customer</button>
    </div>
  );
}

export default CustomerBlock;
